window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dcf9854bbb76951e"]={"versions": [{"id": "FIG-dcf9854bbb76951e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell- / Konfigurationsausschnitt, Paketrahmen <code>HM_HealthChannel</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R20-11), Spezifikation <em>Platform Health Management</em> (PHM).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für die <strong>Health-Channel-Supervision</strong>. Im Gegensatz zu kontrollflussbasierten Mechanismen (Alive-, Deadline- und Logical-Supervision über Checkpoints) dient der Health Channel der statischen und zustandsbasierten Überwachung diskreter System-, Hardware- oder Applikationszustände (z. B. Sensorausfall, Speicherfehler, interne Degradation).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>HealthChannel</code> (Klasse):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert einen logischen Überwachungskanal innerhalb des PHM.\n</li><li><em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>Name</code>: Eindeutiger Bezeichner des Überwachungskanals.\n</li><li><code>ID</code>: Numerische Kennung zur internen Adressierung und Laufzeit-Identifikation bei IPC-/API-Aufrufen.\n</li><li><code>HealthStatusInitValue</code>: Initialer Gesundheitszustand, der dem Kanal beim Systemstart bzw. vor dem Eintreffen der ersten Statusmeldung zugewiesen wird.\n</li></ul>\n</li></ul>\n</li><li><strong><code>HealthStatus</code> (Klasse):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert einen diskreten, gültigen Zustandswert, den der zugehörige Kanal annehmen kann (z. B. <code>OK</code>, <code>DEGRADED</code>, <code>FATAL_ERROR</code>).\n</li><li><em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>Name</code>: Symbolischer Bezeichner des Zustands.\n</li><li><code>ID</code>: Numerischer Enumerate-Wert, der über die Laufzeitschnittstelle übertragen wird.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition (<code>HealthChannel</code> ◆--- <code>HealthStatus</code>):</strong> Ein <code>HealthChannel</code> besitzt die vollständige Existenzabhängigkeit (Lebenszyklus-Hoheit) über seine zugeordneten <code>HealthStatus</code>-Instanzen. Ein Zustandswert existiert nur im Kontext seines Kanals (1 zu $1..\\ast$).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Beim Hochfahren der Adaptive Application und des PHM-Daemons befindet sich der Kanal im Zustand <code>HealthStatusInitValue</code>.\n</li><li><strong>Laufzeit-Trigger (Meldung):</strong> Eine überwachte Entität (Applikation, Treiber oder HW-Monitor) meldet ihren Status via IPC/API (<code>ReportHealthStatus(HealthChannelId, HealthStatusId)</code>) synchron an die lokale PHM-Laufzeitbibliothek.\n</li><li><strong>Validierung &amp; Zustandsübergang:</strong> Der PHM-Daemon prüft, ob die gemeldete <code>HealthStatusId</code> Teil der für den Kanal konfigurierten <code>HealthStatus</code>-Menge ist. Bei Übereinstimmung wechselt der Kanalzustand.\n</li><li><strong>Auswertung &amp; Recovery:</strong> Der aktuelle Zustand speist die PHM-Regel-Engine (<em>Supervision Condition</em> / <em>Logical Expression</em>):\n<ul class=\"fig-list\"><li>Verlässt der Kanal den Normalzustand oder nimmt einen definierten Fehlerstatus ein, wird die zugeordnete <em>Recovery Action</em> getriggert (z. B. Prozessneustart über <em>Execution Management</em>, Transition über <em>State Management</em> oder Fehlereintrag via <em>Diagnostic Management</em>).\n</li><li>Bei Meldung unkonfigurierter IDs greift die Fehlerbehandlung des PHM (z. B. Reporting an die Logging/Security-Infrastruktur).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurationsvertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>Für jeden Kanal müssen alle erwarteten Statuswerte inklusive Initialzustand (<code>HealthStatusInitValue</code>) lückenlos im Manifest modelliert werden. Nicht deklarierte IDs zur Laufzeit führen zu API-Fehlern (<code>ara::phm</code>-Fehlercodes) und verwerfen die Meldung.\n</li></ul>\n</li><li><strong>API &amp; Applikations-Entwicklung (<code>ara::phm</code>):</strong>\n<ul class=\"fig-list\"><li>Applikationen instanziieren ein kanalbezogenes Interface-Objekt (z. B. <code>ara::phm::HealthChannel</code>).\n</li><li>Die Aufrufe sollten zustandsändernd oder bei Erreichen kritischer Degradationsstufen erfolgen; sie erfordern deterministische Zuordnung der im Manifest definierten numerischen IDs zu lokalen Enums.\n</li></ul>\n</li><li><strong>Stack- &amp; Plattform-Integration:</strong>\n<ul class=\"fig-list\"><li>Der PHM-Daemon muss threadsicher und nicht-blockierend ausgelegt sein, um Meldungen mehrerer Channels aus verschiedenen Prozessen/Kernen ohne Priority-Inversion zu konsolidieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-47c0deeb1a16caa4", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell- / Konfigurationsausschnitt, Paketrahmen <code>HM_HealthChannel</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R20-11), Spezifikation <em>Platform Health Management</em> (PHM).\n</li><li><strong>Technischer Zweck:</strong> Definition der Metamodell-Struktur für die <strong>Health-Channel-Supervision</strong>. Im Gegensatz zu kontrollflussbasierten Mechanismen (Alive-, Deadline- und Logical-Supervision über Checkpoints) dient der Health Channel der statischen und zustandsbasierten Überwachung diskreter System-, Hardware- oder Applikationszustände (z. B. Sensorausfall, Speicherfehler, interne Degradation).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>HealthChannel</code> (Klasse):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert einen logischen Überwachungskanal innerhalb des PHM.\n</li><li><em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>Name</code>: Eindeutiger Bezeichner des Überwachungskanals.\n</li><li><code>ID</code>: Numerische Kennung zur internen Adressierung und Laufzeit-Identifikation bei IPC-/API-Aufrufen.\n</li><li><code>HealthStatusInitValue</code>: Initialer Gesundheitszustand, der dem Kanal beim Systemstart bzw. vor dem Eintreffen der ersten Statusmeldung zugewiesen wird.\n</li></ul>\n</li></ul>\n</li><li><strong><code>HealthStatus</code> (Klasse):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert einen diskreten, gültigen Zustandswert, den der zugehörige Kanal annehmen kann (z. B. <code>OK</code>, <code>DEGRADED</code>, <code>FATAL_ERROR</code>).\n</li><li><em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>Name</code>: Symbolischer Bezeichner des Zustands.\n</li><li><code>ID</code>: Numerischer Enumerate-Wert, der über die Laufzeitschnittstelle übertragen wird.\n</li></ul>\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition (<code>HealthChannel</code> ◆--- <code>HealthStatus</code>):</strong> Ein <code>HealthChannel</code> besitzt die vollständige Existenzabhängigkeit (Lebenszyklus-Hoheit) über seine zugeordneten <code>HealthStatus</code>-Instanzen. Ein Zustandswert existiert nur im Kontext seines Kanals (1 zu $1..\\ast$).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Beim Hochfahren der Adaptive Application und des PHM-Daemons befindet sich der Kanal im Zustand <code>HealthStatusInitValue</code>.\n</li><li><strong>Laufzeit-Trigger (Meldung):</strong> Eine überwachte Entität (Applikation, Treiber oder HW-Monitor) meldet ihren Status via IPC/API (<code>ReportHealthStatus(HealthChannelId, HealthStatusId)</code>) synchron an die lokale PHM-Laufzeitbibliothek.\n</li><li><strong>Validierung &amp; Zustandsübergang:</strong> Der PHM-Daemon prüft, ob die gemeldete <code>HealthStatusId</code> Teil der für den Kanal konfigurierten <code>HealthStatus</code>-Menge ist. Bei Übereinstimmung wechselt der Kanalzustand.\n</li><li><strong>Auswertung &amp; Recovery:</strong> Der aktuelle Zustand speist die PHM-Regel-Engine (<em>Supervision Condition</em> / <em>Logical Expression</em>):\n<ul class=\"fig-list\"><li>Verlässt der Kanal den Normalzustand oder nimmt einen definierten Fehlerstatus ein, wird die zugeordnete <em>Recovery Action</em> getriggert (z. B. Prozessneustart über <em>Execution Management</em>, Transition über <em>State Management</em> oder Fehlereintrag via <em>Diagnostic Management</em>).\n</li><li>Bei Meldung unkonfigurierter IDs greift die Fehlerbehandlung des PHM (z. B. Reporting an die Logging/Security-Infrastruktur).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurationsvertrag (ARXML):</strong>\n<ul class=\"fig-list\"><li>Für jeden Kanal müssen alle erwarteten Statuswerte inklusive Initialzustand (<code>HealthStatusInitValue</code>) lückenlos im Manifest modelliert werden. Nicht deklarierte IDs zur Laufzeit führen zu API-Fehlern (<code>ara::phm</code>-Fehlercodes) und verwerfen die Meldung.\n</li></ul>\n</li><li><strong>API &amp; Applikations-Entwicklung (<code>ara::phm</code>):</strong>\n<ul class=\"fig-list\"><li>Applikationen instanziieren ein kanalbezogenes Interface-Objekt (z. B. <code>ara::phm::HealthChannel</code>).\n</li><li>Die Aufrufe sollten zustandsändernd oder bei Erreichen kritischer Degradationsstufen erfolgen; sie erfordern deterministische Zuordnung der im Manifest definierten numerischen IDs zu lokalen Enums.\n</li></ul>\n</li><li><strong>Stack- &amp; Plattform-Integration:</strong>\n<ul class=\"fig-list\"><li>Der PHM-Daemon muss threadsicher und nicht-blockierend ausgelegt sein, um Meldungen mehrerer Channels aus verschiedenen Prozessen/Kernen ohne Priority-Inversion zu konsolidieren.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-dcf9854bbb76951e", "to": "FIG-47c0deeb1a16caa4", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
